var measures = [
 { id: "Amendment 81", title: "Report certain charged people to federal immigration authorities", thr: "55% needed", yes: "Law enforcement must notify federal Homeland Security within 72 hours of charging someone whose lawful presence cannot be confirmed. The ballot title covers people charged with a violent crime, or with any crime if they have a prior felony. The Blue Book says this includes any prior felony, however old.", no: "Current law stays. It allows some cooperation with federal authorities in criminal matters and limits involvement in civil immigration enforcement.", fiscal: "About $60,000 for state system updates. Local costs are not estimated.", pro: "Violent and repeat offenders should be reported for possible enforcement, and a single statewide standard is more consistent.", con: "It weakens due process and the presumption of innocence, key terms are undefined, and it could erode community trust in police.", who: "Backed by Advance Colorado and the A Brighter Colorado committee. Opposed by Colorado Communities First, Vote Common Sense and The People's No.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Amendment 82", title: "Right to buy and sell natural gas for homes and businesses", thr: "55% needed", yes: "Creates a constitutional right for consumers to buy natural gas for cooking or heating, and for distributors and utilities to sell it.", no: "Current law and regulation stay.", fiscal: "No dollar figures. The Blue Book says it may minimally increase state spending and local legal costs.", pro: "Gas is affordable and reliable in extreme cold, and access would be protected from state or local interference.", con: "Gas contributes to climate change and air pollution, and a constitutional right would limit efforts to cut emissions.", who: "Backed by Advance Colorado. Opposed by the No Pollution in the Constitution committee, funded almost entirely by Conservation Colorado.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Amendment 83", title: "Right to hunt and fish", thr: "55% needed", yes: "Creates a constitutional right to hunt and fish certain wildlife, and makes hunting and fishing the preferred way to manage wildlife populations.", no: "Hunting and fishing continue under existing law.", fiscal: "Not expected to change state spending much in the near term. Legal costs could rise by an amount that cannot be estimated.", pro: "Protects against future restrictions, matches 24 other states and supports wildlife funding and the economy.", con: "Recreation should not be a fundamental constitutional right, Colorado already leads in conservation, and vague language could invite costly lawsuits.", who: "Backed by the International Order of T. Roosevelt, the Theodore Roosevelt Conservation Alliance and Safari Club International.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Amendment 84", title: "ID number and signature required on mail ballots", thr: "55% needed", yes: "Mail ballots must include identification information along with the voter's signature. A process to correct missing or wrong information is included.", no: "Signature-only verification continues.", fiscal: "State and local costs of up to $2.7 million in 2026-27 and up to $1.2 million a year after, with about 45% of county costs reimbursed by the state.", pro: "ID is more consistent than signature matching, strengthens security, and most voters already have a qualifying ID.", con: "An unnecessary burden, eligible ballots could go uncounted over small errors, and it could discourage mail voting.", who: "Backed by the Coalition for American Prosperity and Growth, Advance Colorado and the Colorado Voter Trust Initiative. Opposed by Vote Common Sense and Defend Our Ballots.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Amendment 85", title: "Plain-language ballot titles at an eighth-grade level", thr: "55% needed", yes: "Ballot titles must be in plain language at no higher than an eighth-grade reading level, and laws could not interfere with that rule.", no: "Current law stays. It requires plain language but sets no grade level.", fiscal: "May slightly increase workload for the Title Board. No dollar figures.", pro: "A constitutional standard helps voters understand titles and stops future changes that make them more confusing.", con: "Unnecessary, the terms are vague, and it could block laws that add helpful information to titles.", who: "Backed by Advance Colorado. Opposed by Vote Common Sense.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"] },
 { id: "Amendment 86", title: "Approval for congressional redistricting outside a scheduled year", thr: "55% needed", yes: "Any change to congressional districts outside a scheduled redistricting year must be approved by the Independent Congressional Redistricting Commission and adopted by the Colorado Supreme Court.", no: "Current law stays, with districts redrawn every ten years.", fiscal: "About $370,000 in any year the commission has to meet.", pro: "Keeps partisan politics out of redistricting, ensures public participation and protects the commission voters created in 2018.", con: "An unnecessary barrier to new districts, and voters rather than the commission should have the final word.", who: "Backed by Advance Colorado. No opposing committee was named in the sources we read.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"] },
 { id: "Amendment 87", title: "Graduated state income tax", thr: "55% needed", yes: "Replaces the flat 4.4% income tax rate with graduated rates (table below). The new revenue goes to K-12 education, health care and early childhood care, and is exempt from the TABOR limit.", no: "The flat 4.4% rate stays.", fiscal: "The Blue Book estimates about $958 million more in 2026-27 (a half year) and about $1.97 billion in 2027-28, with a maximum of $2.7 billion. Taxpayers with Colorado taxable income under about $510,800 would pay less, and those at or above it would pay more.", pro: "Cuts taxes for about 97% of taxpayers, ties rates to ability to pay and funds services during federal cuts.", con: "A multibillion-dollar tax increase that could push high earners out of state, with brackets not indexed to inflation, and it weakens the flat tax and TABOR.", who: "Backed by Protecting Colorado's Future, a coalition of progressive groups. Opposed by Americans for Prosperity Colorado and Your Family's Future Alliance. Proposition 136 competes with it.", table: [["Income", "Rate"], ["$25,000 or less", "3.7%"], ["$25,001 to $100,000", "4.2%"], ["$100,001 to $500,000", "4.4%"], ["$500,001 to $750,000", "7.4%"], ["$750,001 to $1,000,000", "7.9%"], ["Over $1,000,000", "8.4%"]], src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Proposition NN", title: "Keep TABOR revenue for K-12 education", thr: "Majority needed", yes: "The state may keep some or all revenue TABOR would otherwise refund, up to a limit tied to public education spending. The money goes to K-12 education and children's programs, and after ten years to other purposes the legislature sets.", no: "Current TABOR refunds and funding levels stay.", fiscal: "Reduces TABOR refunds by about $330 million in 2026-27 and $521 million in 2027-28, which eliminates refunds both years.", pro: "Raises teacher pay, reduces class sizes and expands career and technical education using money already collected.", con: "Works like a tax increase because it removes refunds, school funding has risen while enrollment has fallen, and the state should cut waste first.", who: "Referred to the ballot by the Democratic-led legislature. Backed by the Yes for Colorado Kids committee. No opposing committee was named in the sources we read.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"] },
 { id: "Proposition 132", title: "Fentanyl penalties", thr: "Majority needed", yes: "Possessing any amount of fentanyl becomes a felony. Distributing any amount carries a mandatory prison sentence of 8 to 32 years. Some options to reduce penalties are removed.", no: "Minor possession stays a misdemeanor, distribution penalties stay tiered by quantity, and reduction options stay.", fiscal: "State spending up about $0.9 million in the first budget year and $8.9 million in the second, rising to about $68 million by year five.", pro: "Fentanyl is deadly enough to warrant stronger penalties, and mandatory sentences protect the public and may deter use.", con: "Unlikely to reduce use or overdose deaths, may discourage people from seeking treatment or calling for help, and shifts money from treatment to prisons.", who: "Backed by Advance Colorado and the A Brighter Colorado committee. Opposed by Coloradans for Real Safety Solutions, The People's No and Vote Common Sense.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"] },
 { id: "Proposition 133", title: "Human trafficking of a minor", thr: "Majority needed", yes: "Child sex trafficking carries life in prison without parole, and the crime expands to include buying sexual activity with a minor.", no: "The existing Class 2 felony stays, with 8 to 48 years in prison plus mandatory parole.", fiscal: "Corrections costs begin in about 14 years and reach roughly $540,000 a year by the third year of impact.", pro: "The crime causes serious, lasting harm, a life sentence is clear and certain, and it prevents offenders from harming more children.", con: "Harsher sentences are unlikely to deter trafficking, may punish coerced victims, may make victims less likely to report, and take away judges' discretion.", who: "Backed by Protect Kids Colorado. No opposition was identified.", src: ["2026 Blue Book", "https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf"] },
 { id: "Proposition 134", title: "School sports by biological sex", thr: "Majority needed", yes: "Every school-based team or sport must be designated male-only, female-only or coeducational, and schools and districts must adopt sex-eligibility policies.", no: "Schools, districts and athletic associations keep setting their own policies under current state and federal law.", fiscal: "No dollar figures. State costs are indeterminate and tied to possible enforcement by the Department of Education.", pro: "Female athletes should compete against females, a statewide standard is consistent, and physical differences affect strength and injury risk.", con: "There is no clear way to verify eligibility, which could lead to invasive testing or targeting, and could increase harassment and exclusion of students.", who: "Backed by Protect Kids Colorado. Opposed by Families Not Politics, No on 134 and 135 and The People's No.", src: ["Blue Book, Prop 134", "https://leg.colorado.gov/ballots/male-and-female-participation-in-school-and-collegiate-sports-2/files/blue-book"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Proposition 135", title: "Surgery on minors for sex or gender transition", thr: "Majority needed", yes: "Prohibits surgeries on minors that alter biological sex characteristics in response to the minor's perception of sex or gender, with certain exceptions. Bars government funds, Medicaid and private insurance from paying for them.", no: "Current Colorado law stays, which allows access and lets public and private insurance pay.", fiscal: "No dollar figures. The Blue Book expects any impact on state and local spending to be minimal.", pro: "Minors lack the maturity for permanent medical decisions, more long-term data is needed, and some minors may regret irreversible surgery.", con: "The ban is too broad, with narrow exceptions, and could delay recommended care that families and providers agree on.", who: "Backed by Protect Kids Colorado. Opposed by Families Not Politics, No on 134 and 135, The People's No and Rocky Mountain Equality.", src: ["Blue Book, Prop 135", "https://leg.colorado.gov/ballots/prohibit-surgery-on-minors-in-response-to-perception-of-sex-or-gender-2/files/blue-book"], src2: ["Colorado Politics, Oct 2, 2026", CPOL + "2026/10/02/gender-surgeries-minors-proposition-135-colorado/"] },
 { id: "Proposition 136", title: "Cap on the state income tax rate", thr: "Majority needed", yes: "Makes the current 4.4% rate the legal maximum for individuals and corporations, starting January 1, 2027.", no: "The 4.4% rate continues, but no new limit is written into law.", fiscal: "The Blue Book says no fiscal impact.", pro: "Reinforces the 2022 voter-approved rate, which supporters call fair and among the lowest in the country.", con: "Meant to create legal uncertainty for Amendment 87 and could lead to a costly court fight. Raising rates already requires a vote.", who: "Backed by Advance Colorado. No committee was named in the sources we read. It competes with Amendment 87.", src: ["Blue Book, Prop 136", "https://www.leg.colorado.gov/ballots/income-tax-rate-limit-2/files/blue-book"] },
 { id: "Proposition 137", title: "Sporting goods sales tax for conservation and wildfire prevention", thr: "Majority needed", yes: "Sends existing sales tax revenue from sporting goods to conservation, wildfire mitigation and outdoor recreation programs, and exempts it from TABOR. Tax rates and prices do not change.", no: "The revenue stays in the general budget under the TABOR limit and is spent on legislative priorities or refunded.", fiscal: "$175.0 million transferred in 2027-28 and $180.2 million in 2028-29 and after. Tax refunds fall by the same amount, and some sales tax refunds are eliminated for at least 2027-28.", pro: "Funds land protection, wildfire and watershed work without raising taxes or prices, as federal support becomes less reliable.", con: "Works like a tax increase because it reduces future refunds, diverts money from health care and education, and limits lawmakers' flexibility.", who: "Backed by The Nature Conservancy and other environmental groups. Opposed by the Protect Colorado's Land, Communities and Tax Dollars committee.", src: ["Blue Book, Prop 137", "https://leg.colorado.gov/ballots/direct-sporting-goods-sales-tax-revenue-for-conservation-2/files/blue-book"], src2: ["Colorado Politics, Sep 25, 2026", CPOL + "2026/09/25/major-donors-fuel-colorado-ballot-measure-fights-across-the-state/"] },
 { id: "Larimer Ballot Issue 1A", title: "0.3% countywide sales and use tax", thr: "Majority needed", yes: "A new 0.3% countywide sales and use tax (30 cents per $100) starting January 1, 2027, raising the county rate from 1.05% to 1.35%. It funds wildfire and natural hazard resilience, roads, bridges, trails and parks, and emergency response and public services. Food for home use, gasoline, diapers, prescription drugs and period products are exempt.", no: "No new tax.", fiscal: "Raises up to $34.5 million a year (county notice). County spending was $304.1 million in 2022 and is estimated at $406.4 million in 2026.", pro: "The county says prevention costs less than recovery after fires like Cameron Peak, and that dedicated funding is needed. Supporters include Commissioners Jody Shadduck-McNally and Kristin Stephens and Sheriff John Feyen.", con: "Adds $34.5 million a year in spending without a matching benefit to all taxpayers. Sales tax revenue already grows with inflation and population, and the notice estimates about $90 a year less buying power per household member. That estimate is the opponents'.", who: "Placed on the ballot by the county commissioners. The county page names no organized opposition.", src: ["County TABOR notice", "https://www.larimer.gov/sites/default/files/tabor-notice-07-final.pdf"], src2: ["Larimer County news, Aug 28, 2026", "https://www.larimer.gov/spotlights/2026/08/28/larimer-county-commissioners-place-community-resilience-and-needs-sales-tax-measure-november-ballot"] },
 { id: "Rail District Ballot Issue 7A", title: "Front Range Passenger Rail tax and debt", thr: "Majority needed", yes: "A new 0.333% sales and use tax inside the Front Range Passenger Rail District (about 33 cents per $100) to build and run passenger rail, with debt authority of $580 million.", no: "No new district tax or debt.", fiscal: "About $295 million a year, per news reports. Reporting says starter service between Fort Collins and Denver is planned by 2029 with or without the tax, and service to Pueblo by 2032 if it passes.", pro: "The district board chair calls I-25 a single point of failure for the economy and says rail adds redundancy. The board voted 14 to 1 to refer it.", con: "The Independence Institute's Randal O'Toole expects it to cost far more than projected. The Denver Gazette editorial board said Colorado Springs and Pueblo get the short end.", who: "Referred by the district board. Rep. Joe Neguse and the Colorado Rail Passenger Association are named as supporters.", note: "Only voters inside the district count. Some voters outside it were sent this question by mistake. If it is not on your ballot, skip it.", src: ["Colorado Politics, Oct 10, 2026", "https://www.coloradopolitics.com/2026/10/10/coco-train-ballot-error-election-solution/"], src2: ["Denver7, Oct 2026", "https://www.denver7.com/news/local-news/some-voters-in-colorado-are-seeing-issue-7a-about-the-front-range-passenger-rail-when-they-shouldnt"] }
];

