 { h: "County offices", l: ["Commissioner, District 1 (check if it is on your ballot): Shane Atkinson (D), Marc Roberson (R), Stephen Fowler (Center)", "Clerk and Recorder: Tina Harris (R), Kenneth Forsythe (D)", "Treasurer: Joann Ginal (D), Steve Olson (R)", "Assessor: Patrick Edwards (R), Bob Overbeck (D), Sam Bradley (Forward)", "Sheriff: John J. Feyen (R), unopposed", "Surveyor: Tom Donnelly (R), unopposed", "Coroner: Stephen Hanks (D), unopposed"] },
 { h: "Judges (retain: yes or no)", l: ["Colorado Supreme Court: William W. Hood III", "Court of Appeals: Rebecca Rankin Freyre, Elizabeth L. Harris, Katharine E. Lum, Pax Moultrie, Karl L. Schock, Grant Sullivan", "Larimer County Court: Katharine Ellison, Thomas L. Lynch, Matthew R. Zehe"] }
